export type NodeType = 'submit' | 'warehouse' | 'event' | 'reminder' | 'holiday' | 'fbm' | 'supply'
export type ChannelType = 'promo' | 'fba' | 'fbm' | 'event' | 'spring'

export interface PeakSeasonNode {
  id: string
  date: string        // YYYY-MM-DD
  label: string       // 节点名
  shortLabel?: string // 胶囊短标
  type: NodeType
  channel: ChannelType // 渠道分类
  month: number       // 用于排序，1-12
  day: number         // 具体日期
  actions: string[]   // 该做什么
  tools: string[]     // 用哪个工具
  tips?: string       // 额外提示
  isMajor?: boolean   // 是否是重大活动（用于顶部倒计时胶囊）
}

export interface PeakSeasonGroup {
  key: string
  title: string
  subtitle: string
  nodes: PeakSeasonNode[]
}

